const $=s=>document.querySelector(s);
const groups={panel:'Корпус',worktop:'Корпус',door:'Фасады',drawer:'Фасады',shelf:'Наполнение',interior:'Наполнение',handle:'Фурнитура',hardware:'Фурнитура',support:'Фурнитура',light:'Фурнитура',appliance:'Техника',insert:'Техника'};
export function installEasyUI({scene,current,advanced,assembly,materials,commit,inspectorTab,showPanel,toast}){
 let exiting=false,filter='Все',lastList='',expert=false;
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');
 try{expert=localStorage.getItem('batesto-ui-expert')==='true';}catch{}
 document.body.dataset.ui=expert?'expert':'simple';
 const launch=document.createElement('section');launch.id='easy-actions';launch.innerHTML='<p class="easy-help">Выберите мебель в комнате. Здесь можно изменить её размер, цвет и устройство.</p><button id="disassemble-open" class="easy-primary">Разобрать и настроить детали <span>↗</span></button><button id="easy-open-front" class="easy-secondary">Открыть дверцы и ящики</button>';
 $('#module-pane').prepend(launch);
 const switcher=document.createElement('button');switcher.id='expert-toggle';switcher.className='expert-toggle';$('.inspector-foot').before(switcher);
 const list=document.createElement('section');list.id='disassembly-list';list.hidden=true;list.innerHTML='<div class="disassembly-heading"><span class="eyebrow">УСТРОЙСТВО МЕБЕЛИ</span><h2>Из чего состоит</h2><p>Нажмите на деталь в сцене или выберите её здесь.</p></div><div class="disassembly-search"><input id="part-search" type="search" placeholder="Например, ручка или полка" aria-label="Найти деталь"><select id="part-category" aria-label="Группа деталей"></select></div><div id="easy-part-list"></div>';
 $('.library').append(list);
 $('#part-category').innerHTML=['Все','Корпус','Фасады','Наполнение','Фурнитура','Техника'].map(g=>`<option>${g}</option>`).join('');
 const bar=document.createElement('section');bar.id='disassembly-toolbar';bar.hidden=true;bar.innerHTML='<div class="disassembly-topline"><div><span class="eyebrow">РАЗОБРАТЬ МОДУЛЬ</span><strong id="disassembly-name"></strong></div><button id="disassembly-exit">← Вернуться к кухне</button></div><div class="disassembly-controls"><button id="disassembly-play">Разобрать</button><button id="disassembly-assemble">Собрать</button><label>Раздвинуть детали <output id="disassembly-value">0%</output><input id="disassembly-amount" type="range" min="0" max="100" value="0"></label><select id="disassembly-layout" aria-label="Способ разборки"><option value="spatial">По устройству</option><option value="layers">Послойно</option></select><button id="disassembly-fit" aria-label="Показать все детали">⌖</button></div><p id="disassembly-hint" role="status">Нажмите на деталь, чтобы изменить её материал или устройство.</p>';
 $('.stage').append(bar);
 const settings=document.createElement('div');settings.className='disassembly-options';settings.innerHTML='<label>Показать <select id="disassembly-level"><option value="assemblies">Основные узлы</option><option value="parts">Все детали</option></select></label><label><input id="disassembly-guides" type="checkbox" checked> Линии сборки</label>';bar.append(settings);
 $('#disassembly-level').onchange=e=>{scene.exploder.setLevel(e.target.value);scene.frameExploded();scene.select(scene.selected);scene.dirty=true;};
 $('#disassembly-guides').onchange=e=>{scene.exploder.showGuides=e.target.checked;scene.exploder.apply();scene.dirty=true;};
 function frame(){const value=Math.round(scene.exploder.amount*100);$('#disassembly-amount').value=value;$('#disassembly-value').textContent=value+'%';if(exiting&&!scene.exploder.animation){exiting=false;scene.endExploded();$('#module-level').click();render();}}
 function animate(to,exit=false){exiting=exit;scene.exploder.animateTo(to,performance.now(),reduced.matches);scene.dirty=true;frame();}
 function start(){if(!current()){toast('Сначала выберите мебель в комнате');return;}assembly.detach();if(!scene.startExploded())return;document.body.dataset.exploded='true';$('#disassembly-layout').value=scene.exploder.layout;$('#part-search').value='';filter='Все';$('#part-category').value=filter;lastList='';
  const first=scene.parts().find(p=>['door','drawer'].includes(p.kind))||scene.parts()[0];if(first)advanced.selectPart(first.id);inspectorTab('parts');showPanel('');animate(1);render();scene.frameExploded();}
 function choose(id){if(scene.exploder.scopeId){const e=scene.exploder.entries.find(e=>e.node.userData.partId===id);if(e&&!scene.exploder.inScope(e.node))scene.exploder.setScope(null);}const entry=scene.exploder.entries.find(e=>e.node.userData.partId===id);if(entry?.nested&&scene.exploder.level!=='parts'){scene.exploder.setLevel('parts');$('#disassembly-level').value='parts';scene.frameExploded();}advanced.selectPart(id);render();}
 function renderParts(){const parts=scene.parts(),selected=advanced.selectedPart(),query=$('#part-search').value.toLowerCase();const key=JSON.stringify([parts,selected,filter,query,current()?.details]);if(key===lastList)return;lastList=key;$('#easy-part-list').replaceChildren();
  const visible=parts.filter(p=>(filter==='Все'||groups[p.kind]===filter)&&p.label.toLowerCase().includes(query));
  for(const p of visible){const button=document.createElement('button');button.className='easy-part';button.dataset.easyPart=p.id;button.setAttribute('aria-pressed',String(p.id===selected));const symbol=document.createElement('span');symbol.className='easy-part-symbol';symbol.textContent=({handle:'⌁',hardware:'⚙',shelf:'▰',door:'▯',drawer:'▤',worktop:'▱'})[p.kind]||'▧';const text=document.createElement('span');const name=document.createElement('strong');name.textContent=p.label;const description=document.createElement('small');description.textContent=groups[p.kind]||'Деталь';text.append(name,description);button.append(symbol,text);button.onclick=()=>choose(p.id);$('#easy-part-list').append(button);}
  if(!visible.length){const p=document.createElement('p');p.className='panel-note';p.textContent='Таких деталей нет. Попробуйте другое название.';$('#easy-part-list').append(p);}
 }
 function render(){const active=scene.exploder.active,m=current();document.body.dataset.exploded=String(active);$('#mobile-library').textContent=active?'☷ Детали':'＋ Мебель';list.hidden=bar.hidden=!active;launch.hidden=!m;$('#disassemble-open').disabled=!m;$('#easy-open-front').disabled=!m||m.locked;$('#easy-open-front').textContent=m?.open>0?'Закрыть дверцы и ящики':'Открыть дверцы и ящики';switcher.textContent=expert?'Вернуться в простой режим':'Расширенные настройки';switcher.setAttribute('aria-pressed',String(expert));if(active){$('#disassembly-name').textContent=m?.name||'Модуль';renderParts();frame();}$('#part-isolate').disabled=active;}
 switcher.onclick=()=>{expert=!expert;document.body.dataset.ui=expert?'expert':'simple';try{localStorage.setItem('batesto-ui-expert',String(expert));}catch{}render();};
 $('#disassemble-open').onclick=start;$('#explode-pro-open').onclick=start;
 $('#easy-open-front').onclick=()=>{const m=current();if(!m||m.locked)return;m.open=m.open>0?0:100;for(const d of Object.values(m.details||{}))if('open' in d)d.open=m.open;commit({rebuild:true});};
 $('#disassembly-play').onclick=()=>animate(1);$('#disassembly-assemble').onclick=()=>animate(0);$('#disassembly-exit').onclick=()=>animate(0,true);
 $('#disassembly-amount').oninput=e=>{exiting=false;scene.exploder.setAmount(+e.target.value/100);scene.dirty=true;frame();};
 $('#disassembly-layout').onchange=e=>{scene.exploder.setLayout(e.target.value);scene.frameExploded();scene.dirty=true;};
 $('#disassembly-fit').onclick=()=>scene.frameExploded();$('#part-search').oninput=renderParts;$('#part-category').onchange=e=>{filter=e.target.value;renderParts();};
 scene.onExplodedFrame=frame;scene.onPartHover=name=>{$('#disassembly-hint').textContent=name?name+' · нажмите, чтобы настроить':'Нажмите на деталь, чтобы изменить её материал или устройство.';};
 scene.onExplodedExit=()=>{document.body.dataset.exploded='false';list.hidden=bar.hidden=true;exiting=false;$('#part-isolate').disabled=false;};
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&scene.exploder.active&&!document.querySelector('dialog[open]')){e.preventDefault();e.stopImmediatePropagation();scene.endExploded();$('#module-level').click();render();}},true);
 for(const key of ['thickness','legs','handleColor','doors'])document.querySelector(`[data-prop="${key}"]`)?.closest('label')?.classList.add('expert-control');
 document.querySelector('[data-prop="thickness"]')?.closest('.field-grid')?.classList.add('expert-control');
 $('#part-select').closest('label').classList.add('part-selector-row');for(const key of ['floorRoughness','window','exposure'])document.querySelector(`[data-room="${key}"]`)?.closest('.property-group')?.classList.add('expert-control');document.querySelector('[data-room=wallThickness]')?.closest('.field-grid')?.classList.add('expert-control');
 render();return {render,start};
}
